actions.script:
if (!ec.user.userId) {
    ec.web.sendJsonError(401, 'Authentication required')
} else {
    const qvtLib = ec.resource.script('component://webroot/screen/includes/QvtConfig.js')
    const localeTag = String(ec.user.locale || 'en_US').replace('_', '-')
    const rumSettings = ec.service.sync().name('org.moqui.monitor.MonitorServices.get#BrowserSettings').disableAuthz().call().settings || null
    const config = qvtLib.build(ec, sri, { staticOnly: true, localeTag: localeTag, quasarLang: qvtLib.quasarLangOf(localeTag), rumSettings: rumSettings })
    config.pageTraceId = ''
    config.server = { name: config.shell.title || ec.web.getHostName(false), moquiVersion: ec.factory.moquiVersion, clientApi: 4 }
    const push = ec.service.sync().name('org.moqui.ui.NotificationServices.get#PushDeviceStatus').disableAuthz().call() || {}
    config.server.features = { nativePush: { providers: ['fcm'], fcmConfigured: push.fcmConfigured === true, registered: push.registered === true } }
    // what an app's inbox source supports beyond the framework's (its operation features), for a client that works
    // offline: internalSendRef (an internal send is made once by its clientRef, so it may be queued) and
    // mailChangesUncovered (the stores the mail change cursor does not cover). Read-only and the user's own, so with
    // no authorization, as the shell's other services here; each provider runs as its app. One that fails is logged.
    const features = config.server.features = Object.assign({}, config.server.features || {})
    try {
        const providers = ec.service.sync().name('org.moqui.ui.ShellServices.call#Providers').parameters({hook: 'inbox-source',
            parameters: {operation: 'features'}}).disableAuthz().call()
        for (const answer of Array.from(providers?.results || [])) {
            if (answer && answer.handled && answer.result) Object.assign(features, answer.result)
        }
        for (const part of Array.from(providers?.failedParts || [])) ec.logger.warn(`Client config features of ${part.sourceId}: ${part.error}`)
    } catch (err) {
        ec.logger.warn(`Client config features not read: ${err && err.message ? err.message : err}`)
    }
    if (ec.message.hasError()) { ec.logger.warn(`Client config features: ${ec.message.errorsString}`); ec.message.clearErrors() }
    ec.web.sendJsonResponse(config)
}

if (!ec.user.userId) ec.web.sendJsonError(401, 'Authentication required')
else {
    ec.service.sync().name('org.moqui.impl.UserServices.revoke#UserDeviceKey').parameters({loginKey: loginKey}).disableAuthz().call()
    if (ec.message.hasError()) ec.web.sendJsonError(400, ec.message.errorsString)
    else ec.web.sendJsonResponse({revoked: true})
}

if (!ec.user.userId) ec.web.sendJsonError(401, 'Authentication required')
else {
    const renewed = ec.service.sync().name('org.moqui.impl.UserServices.renew#UserDeviceKey').disableAuthz().call()
    if (ec.message.hasError()) ec.web.sendJsonError(400, ec.message.errorsString)
    else ec.web.sendJsonResponse({loginKey: renewed.loginKey, thruDate: renewed.thruDate})
}

if (!ec.user.userId) ec.web.sendJsonError(401, 'Authentication required')
else {
    const p = ec.web.parameters
    const out = ec.service.sync().name('org.moqui.ui.NotificationServices.register#PushDevice').parameters({
        provider: p.provider || null, token: p.token || null, appId: p.appId || null, platform: p.platform || null,
    }).disableAuthz().call() || {}
    if (ec.message.hasError()) ec.web.sendJsonError(400, ec.message.errorsString)
    else ec.web.sendJsonResponse({registered: true, subscriptionId: out.subscriptionId})
}

if (!ec.user.userId) ec.web.sendJsonError(401, 'Authentication required')
else {
    const out = ec.service.sync().name('org.moqui.ui.NotificationServices.unregister#PushDevice')
        .parameters({token: ec.web.parameters.token || null}).disableAuthz().call() || {}
    if (ec.message.hasError()) ec.web.sendJsonError(400, ec.message.errorsString)
    else ec.web.sendJsonResponse({deletedCount: out.deletedCount ?? 0})
}

pre-actions.script:
// if user not logged in save current path and params then redirect to Login
if (!ec.user.userId) { ec.web.saveScreenLastInfo(null, null); sri.sendRedirectAndStopRender('/Login'); return }

// The libraries and the client, in the order they load. footer_scripts is written by Footer.html.fancy after the page.
// vue.global.prod.js is the build with the template compiler, which server-merged qvt and the string templates of the m-* components need
// (and unsafe-eval in a CSP). vue.runtime.global.prod.js has no compiler: webapp_qvt_static_only=true loads it, for a deployment whose pages
// get only server-static templates and whose components are precompiled (plans/archive/QvtServerStatic.md, Server compile).
const qvtLib = ec.resource.script('component://webroot/screen/includes/QvtConfig.js')
const localeTag = String(ec.user.locale || 'en_US').replace('_', '-')
const quasarLang = qvtLib.quasarLangOf(localeTag)
const staticOnly = System.getProperty('webapp_qvt_static_only') == 'true'
footer_scripts.add(staticOnly ? '/libs/vue/vue.runtime.global.prod.js' : '/libs/vue/vue.global.prod.js')
footer_scripts.add('/libs/quasar/quasar.umd.prod.js')
footer_scripts.add('/libs/quasar/lang/' + quasarLang + '.umd.prod.js')
// Quasar's icon set of Material Symbols, outlined, which WebrootVue.qvt.js sets; only with the font among the theme's
// stylesheets (a database loaded before it keeps Quasar's Material Icons until the theme data is loaded again)
if (sri.getThemeValues('STRT_STYLESHEET').some((sheet) => String(sheet).includes('/libs/material-symbols/')))
    footer_scripts.add('/libs/quasar/icon-set/material-symbols-outlined.umd.prod.js')
footer_scripts.add('/js/MoquiLib.js')
// Real-user monitoring (telemetry/browser): only for a signed-in user, and right after MoquiLib, so it sees the
// page's errors and requests from the start
const rumSettings = ec.user.userId ? ec.service.sync().name('org.moqui.monitor.MonitorServices.get#BrowserSettings').disableAuthz().call().settings || null : null
if (rumSettings) footer_scripts.add('/js/WebrootRum.js')
footer_scripts.add('/js/MoquiL10n.js')
// the chat store and the account menu's status (moqui.chat), before the client, which registers its components
footer_scripts.add('/js/WebrootChat.js')
// Assist: the drawer, its store, transport and follow (moqui.assist), before the client, which registers its components
footer_scripts.add('/js/WebrootAssist.js')
// the Constitution's reading view, reference dialog and the drawer's Rules pane (moqui.constitution)
footer_scripts.add('/js/WebrootConstitution.js')
footer_scripts.add('/js/WebrootReport.js')
// declared actions and panels of the screens (moqui.ext, m-ext-actions, m-ext-panel)
footer_scripts.add('/js/WebrootExt.js')
// the PWA's service worker and Web Push (moqui.push, the account menu's Notifications on this device)
if (ec.user.userId) footer_scripts.add('/js/WebrootPush.js')
// calls: the ring bar, the LiveCall window and m-call (moqui.call), for a signed-in user
if (ec.user.userId) footer_scripts.add('/js/WebrootCall.js')
// and the render functions of its components, precompiled (applied when the client starts, as WebrootVue.qvt.render.js's)
if (ec.user.userId) footer_scripts.add('/js/WebrootCall.render.js')
// the recent sign-in check of sensitive actions (moqui.reauth: confirm who you are again)
if (ec.user.userId) footer_scripts.add('/js/WebrootReAuth.js')
// the crypto device (moqui.crypto): small; its WebAssembly module loads only when a device is needed
if (ec.user.userId) footer_scripts.add('/js/WebrootCrypto.js')
// end-to-end encrypted calls (moqui.callKeys): the call-key protocol; its SFrame worker loads only in such a call
if (ec.user.userId) footer_scripts.add('/js/WebrootCallKeys.js')
// the browser terminal's store and views (moqui.terminal), when this server serves its socket
if (ec.user.userId && System.getProperty('webapp_terminal_endpoint')) footer_scripts.add('/js/WebrootTerminal.js')
// the render functions of the components, precompiled from their templates; WebrootVue.qvt.js applies them when it starts
footer_scripts.add('/js/WebrootVue.qvt.render.js')
footer_scripts.add('/js/WebrootVue.qvt.js')

// The settings of the client: one JSON block in the shell, WebrootVue.qvt.html.fancy; built in QvtConfig.js, which the
// desktop client's clientConfig (above) shares, with this page's session token added.
qvtConfig = qvtLib.build(ec, sri, { staticOnly: staticOnly, localeTag: localeTag, quasarLang: quasarLang, rumSettings: rumSettings })
qvtConfig.sessionToken = ec.web.sessionToken
// conditional QZ Tray scripts, only for a user who turned printing on; the client loads them
